insert into sebsgarden.site_content (id, data) values (1, '{"version": 2, "business": {"name": "Seb’s Garden", "phone": "05 62 70 62 19", "phone_intl": "+213562706219", "address": "Kiffane, Tlemcen 13000, Algérie", "maps_url": "https://www.google.com/maps/search/?api=1&query=Restaurant+Seb%27s+garden+tlemcen", "open": false, "closed_text": "Fermé temporairement depuis le 3 octobre pour un renouveau — « Une page se tourne… ». Suivez la réouverture sur Instagram @restaurant_sebs_garden ou appelez le 05 62 70 62 19.", "instagram": "https://www.instagram.com/restaurant_sebs_garden/", "plus_code": "VMQF+7F", "price_range": "1 000 – 6 000 DA"}, "hero": {"kicker": "Restaurant gastronomique · Kiffane, Tlemcen", "title": "Seb’s *Garden*", "tagline": "Cuisine internationale, cuisine ouverte et salon feutré. Ici, le dîner se joue comme un air de jazz, en douceur."}, "about": {"title": "Une table élégante, *une cuisine ouverte*", "text": "Seb’s Garden est un restaurant gastronomique de Kiffane, à Tlemcen, tourné vers la cuisine internationale : pizzas, pâtes, grillades, salades, desserts et cocktails.", "text2": "Comptoir sur cuisine ouverte, salon avec canapés et musique douce, terrasse, plats végans et un espace pensé pour les enfants — en couple, en famille ou entre amis.", "quote": "Le comptoir spacieux donne sur une cuisine ouverte où les chefs préparent des plats variés et savoureux, élaborés avec des ingrédients frais et de qualité."}, "specialities": ["Cuisine internationale", "Cuisine ouverte", "Pizzas", "Pâtes", "Grillades", "Plats végans", "Cocktails", "Desserts", "Terrasse", "Kiffane · Tlemcen"], "menu": {"note": "Carte à venir : les tarifs ne sont pas encore publiés en ligne (gamme de prix indiquée par Google : 1 000 – 6 000 DA). Appelez-nous pour la carte du jour.", "currency": "DA", "source": "Plats vus sur les photos du restaurant (RestosDZ) et des clients (Google Maps) ; aucune carte avec prix publiée (sebsgarden.com/menu : « Menu d’été prochainement »).", "categories": [{"id": "plats", "title": "Les plats", "desc": "Cuisine internationale préparée en cuisine ouverte. Plats vus sur les photos du restaurant ; aussi cités dans les avis : steak, pâtes aux crevettes ou au pesto de pistache, sushis.", "items": [{"name": "Pizza roquette & tomates cerises", "desc": "", "price": "prix à venir"}, {"name": "Pizza olives & tomates cerises", "desc": "", "price": "prix à venir"}, {"name": "Pâtes au basilic", "desc": "", "price": "prix à venir"}, {"name": "Brochettes mixtes grillées", "desc": "avec riz", "price": "prix à venir"}, {"name": "Viande grillée & légumes", "desc": "", "price": "prix à venir"}, {"name": "Escalope panée", "desc": "haricots verts, pommes de terre", "price": "prix à venir"}]}, {"id": "entrees", "title": "Entrées & salades", "desc": "Salades, soupe et entrées ; plats végans disponibles.", "items": [{"name": "Salade de crevettes", "desc": "", "price": "prix à venir"}, {"name": "Salade tomate-concombre", "desc": "", "price": "prix à venir"}, {"name": "Soupe & tartelette", "desc": "", "price": "prix à venir"}]}, {"id": "boissons", "title": "Desserts & cocktails", "desc": "Desserts, pâtisseries de la vitrine et cocktails.", "items": [{"name": "Cheesecake", "desc": "", "price": "prix à venir"}, {"name": "Dessert au chocolat", "desc": "", "price": "prix à venir"}, {"name": "Pâtisseries", "desc": "", "price": "prix à venir"}, {"name": "Cocktail pastèque", "desc": "", "price": "prix à venir"}]}]}, "hours": [{"day": "Samedi", "open": "11:00", "close": "23:00"}, {"day": "Dimanche", "open": "11:00", "close": "23:00"}, {"day": "Lundi", "open": "11:00", "close": "23:00"}, {"day": "Mardi", "open": "11:00", "close": "23:00"}, {"day": "Mercredi", "open": "11:00", "close": "23:00"}, {"day": "Jeudi", "open": "11:00", "close": "23:00"}, {"day": "Vendredi", "open": "14:00", "close": "23:30"}], "booking": {"open": false, "note": "Le restaurant est fermé temporairement pour renouveau : les réservations en ligne rouvriront avec lui. Laissez-nous un message ou appelez le 05 62 70 62 19."}, "reviews": [{"author": "Avis Google · 5/5 · juillet 2025 (en anglais)", "text": "The best steak I have ever had. Amazing atmosphere. Love from USA 🇺🇸"}, {"author": "Avis Google · 5/5 · juillet 2025 (en anglais)", "text": "We came all the way from London and the food was amazing the waiter he spoke English and French which makes it so much easier for us ✨ I recommend you to try this place"}, {"author": "Avis Google · 4/5 · décembre 2025 (en anglais)", "text": "Great restaurant, the food was delicious, and the service was very good."}], "rating": {"value": "4,5", "count": "787"}, "photos": {"hero": {"label": "Accueil — pizza à la bougie", "alt": "Pizza servie à la bougie sur une table sombre", "src": ""}, "salle": {"label": "La salle", "alt": "La salle de Seb’s Garden : tables dressées, plafond lumineux et banquettes", "src": ""}, "pizza": {"label": "Pizza roquette", "alt": "Pizza à la roquette et aux tomates cerises de Seb’s Garden", "src": ""}, "brochettes": {"label": "Brochettes mixtes", "alt": "Assiette de brochettes grillées et riz", "src": ""}, "pates": {"label": "Pâtes au basilic", "alt": "Pâtes au basilic", "src": ""}, "grillade": {"label": "Grillade & légumes", "alt": "Viande grillée et légumes servis à Seb’s Garden", "src": ""}, "dessert": {"label": "Dessert au chocolat", "alt": "Dessert au chocolat servi à la bougie sur une table sombre", "src": ""}, "cheesecake": {"label": "Cheesecake", "alt": "Part de cheesecake", "src": ""}, "cocktail": {"label": "Cocktail pastèque", "alt": "Cocktail à la pastèque de Seb’s Garden", "src": ""}, "crevettes": {"label": "Salade de crevettes", "alt": "Salade de crevettes servie à Seb’s Garden", "src": ""}, "brochettes2": {"label": "Brochettes (assiette bleue)", "alt": "Brochettes grillées sur une assiette bleue", "src": ""}}}'::jsonb) on conflict (id) do nothing;
